from .generic_oam import GenericOAMSelenium
from taf.ul.sc.exceptions import COAMFunctionalityNotSupported
from functools import wraps
import time


def login_logout_decorator(func):
    @wraps(func)
    def wrapper(self, *args, **kwargs):
        self.connect_to_webui_via_selenium()
        out = func(self, *args, **kwargs)
        time.sleep(10)
        self.selenium_webui.logout()
        return out

    return wrapper


class CoamSelenium(GenericOAMSelenium):
    """"""

    def __init__(self):
        super(CoamSelenium, self).__init__()
        if 'SBTS' in self.get_load_type().split("_")[0]:
            from taf.selenium.sbts import sbts as selenium_coam
        else:
            from taf.selenium.gnb.oam.coam.classical import classical as selenium_coam
        self.selenium_webui = selenium_coam()

    def add_software_file_via_selenium(self, file_path, timeout=90):
        """
        Keyword for selecting one software file(.zip).
        :param file_path: String containing absolute path to .zip file with software.
        :param timeout: int, time for waiting file status element to disappear(optional)
        :return: None
        """
        self.selenium_webui.load_software_package_from_local_drive(file_path=file_path, timeout=timeout)

    def activate_after_download_via_selenium(self, button_status='activate', timeout=15):
        """
        Keyword for clicking "Activate" button at parameters page, has provided param to control whether activate after
        confirm window popped up
        :param button_status: str, only "activate" or "cancel" can be passed in, default is activate.
        :param timeout: int timeout for activate completed
        :return: None
        """
        raise COAMFunctionalityNotSupported(
            "Activate after download is not supported, check start_update_software_via_selenium")

    def start_update_software_via_selenium(self, is_activate=True):
        """
        Click "Start Update" button to execute update process.
        :param is_activate: activate software after download
        :return: None
        """
        self.selenium_webui.software_update(is_activate=is_activate)

    def start_rollback_via_selenium(self):
        """
        Keyword for starting rollback via selenium.

        :return: None
        """
        self.selenium_webui.software_rollback()

    def get_ru_software_version_via_selenium(self):
        """
        Get Active version of SW info in site management page.
        :return: Active version of SW as dict.
        """

    # @login_logout_decorator
    def collect_snapshot_via_selenium(self):
        """
        Go to Diagnostic - Snapshot, click All log files, Local and then Collect snapshot.
        It will be downloaded in /tmp/
        :return: None
        """
        self.selenium_webui.snapshot_collection_settings("All log files", "Local")
        return self.selenium_webui.collect_snapshot()

    # @login_logout_decorator
    def block_hub_via_selenium(self, ru_index=1):
        """
        Block hub
        :return: None
        """
        self.selenium_webui.lock_ru(type_='ASIRMOD', ru_index=ru_index)

    # @login_logout_decorator
    def reset_hub_via_selenium(self, ru_index=1):
        """
        Reset hub
        :return: None
        """
        self.selenium_webui.reset_ru(type_='ASIRMOD', ru_index=ru_index)

    # @login_logout_decorator
    def unlock_hub_via_selenium(self, ru_index=1):
        """
        Unlock hub
        :return: None
        """
        self.selenium_webui.unlock_ru(type_='ASIRMOD', ru_index=ru_index)

    @login_logout_decorator
    def get_active_alarms_list_via_selenium(self):
        """
        Get gNB active alarms.

        :return: list of active alarms
        """
        return self.selenium_webui.get_active_alarm_info()

    @login_logout_decorator
    def get_historic_alarms_list_via_selenium(self):
        """
        Get gNB historic alarms.

        :return: list of history alarms
        """
        return self.selenium_webui.get_history_alarm_info()

    def sw_upgrade_via_selenium(self, path_to_software):
        """
        Load build from a remote location, executes updating.
        :param path_to_software local path to file with build
        :return: None
        """
        self.selenium_webui.load_software_package_from_local_drive(path_to_software)
        self.selenium_webui.software_update()

    def get_sw_version_via_selenium(self):
        """
        Checks current software version.
        :return: string with build name
        """
        self.selenium_webui.check_current_software_version()

    def get_hub_info_via_selenium(self, ru_index):
        """
        Keyword checks information about connected hubs.
        :ru_index: hub number, starting from 1.
        :return: information about hub
        """
        return self.selenium_webui.get_ru_info(type_='ASIRMOD', ru_index=ru_index)

    def set_parameter_value_via_selenium(self, dist_name, filter_param, new_value=None, node_index=None, abbr=None,
                                         timeout=60):
        """
        Keyword sets value in commissioning.
        :dist_name: dist_name in commissioning.
        :filter_param: filter for searching.
        :new_value: new value to set.
        :node_index: node_index in commissioning.
        :abbr: abbr.
        :timeout: timeout in seconds.
        :return: None
        """
        self.selenium_webui.set_parameter_value(dist_name, filter_param, new_value=new_value, node_index=node_index,
                                                abbr=abbr, timeout=timeout)

    def validate_plan_via_selenium(self):
        """
        Keyword keyword is responsible for validating provided plan
        :return: None
        """
        self.selenium_webui.validate_plan()

    def activate_plan_via_selenium(self):
        """
        Keyword keyword is responsible for activating validated plan
        :return: None
        """
        self.selenium_webui.activate_plan()

    def get_ru_info_via_selenium(self, param=None):
        """
        Keyword checks information about connected hub.
        :return: information about hub
        """
        info = self.selenium_webui.get_ru_info()

        if param:
            return info[param]
        return info

    def get_number_of_cells_via_selenium(self, timeout):
        """
        Keyword keyword is responsible for check number of connected cells.
        :timeout: timeout in seconds
        :return: number of cells
        """
        return self.selenium_webui.get_number_of_cells(timeout)

    def get_all_cells_status_via_selenium(self, timeout=120):
        """
        Keyword keyword is responsible for check status of connected cells.
        :return: cells status
        """
        cells_info = []
        for cell in range(1, self.get_number_of_cells_via_selenium(timeout) + 1):
            cells_info.append(self.selenium_webui.get_cell_info(cell)['Status'])

        return cells_info

    def get_led_status_of_an_unit_via_selenium(self, unit, timeout=60):
        """
        Keyword keyword is responsible for check unit led status.
        :unit: unit
        :timeout: timeout in seconds.
        :return: number of cells
        """
        return self.selenium_webui.get_led_status_of_an_unit(unit, timeout=timeout)

    def reset_abil_via_selenium(self):
        """
        Keyword keyword is responsible for reset abil.
        :return: None
        """
        return self.selenium_webui.reset_abil()

    def get_parameter_value_via_selenium(self, name, param):
        """
        Keyword keyword is responsible for check provided parameter value.
        :name: dist name for parameters to filter
        :param: str, param to locate target parameter, cannot be none
        :return: number of cells
        """
        return self.selenium_webui.get_parameter_value(name, param)

    def get_bts_status_via_selenium(self):
        """
        Keyword for getting bts status
        :return: str, status of bts
        """
        return self.selenium_webui.get_bts_status()

    def reset_site_via_selenium(self):
        """
        Keyword keyword is responsible for perform site reset.
        :return: None
        """
        return self.selenium_webui.reset_site()

    def validate_plan_and_check_for_errors_via_selenium(self):
        """
        Keyword for checking if there are no definition, relation and hardware errors after validating plan.
        :return: bool, True if validation was performed without errors, False if there were errors
        """
        self.selenium_webui.validate_plan()
        definition_errors_communicate = self.selenium_webui.get_definition_errors()
        relation_errors_communicate = self.selenium_webui.get_relation_errors()
        hardware_errors_communicate = self.selenium_webui.get_hardware_errors()

        if not definition_errors_communicate and not relation_errors_communicate and not hardware_errors_communicate:
            return True
        else:
            return False

    def software_rollback_via_selenium(self):
        """
        Keyword for performing software rollback
        :return: None
        """
        self.selenium_webui.software_rollback()

    def configuration_reset_via_selenium(self):
        """
        Keyword for performing configuration reset
        :return: None
        """
        self.selenium_webui.configuration_reset()

    def save_bts_configuration_via_selenium(self, save_configuration_type=0,
                                            is_save_planned_parameter_changes_selected=True):
        """
        Keyword for saving bts configuration
        :param save_configuration_type: str, type of save type
                0: Save as SCF - BTS configuration only
                1: Save as full BTS runtime configuration
                2: Save BTS runtime information only
        :param is_save_planned_parameter_changes_selected: bool, save the planned parameter changes or not
        :return str, path to download configuration file
        """

        return self.selenium_webui.save_bts_configuration(save_configuration_type,
                                                          is_save_planned_parameter_changes_selected)

    def disable_screen_lock_via_selenium(self, time_interval=30000):
        """
        Disable screen lock after idle for some minutes.

        :param time_interval: int, event execution time interval, 30000 is 30s
        :return: None
        """
        self.selenium_webui.disable_screen_lock(time_interval)

    def enable_screen_lock_via_selenium(self):
        """
        Enable screen lock  after idle for some minutes.

        :return: None
        """
        self.selenium_webui.enable_screen_lock()

    def continue_after_reload_modal_appear_via_selenium(self, timeout=900):
        """
        Wait for reload message and click confirm.

        :param timeout: timeout for message appearance.
        :return: None
        """
        self.selenium_webui.continue_after_reload_modal_appear(timeout=timeout)

    def load_commissioning_file_and_check_load_status(self, file_path, timeout=60):
        """
        Keyword for loading commissioning file and check load status
        :param file_path: str, scf file path
        :param timeout: int, timeout
        :return: boolean, True or False
        """
        return self.selenium_webui.load_commissioning_file_and_check_load_status(file_path, timeout)

    def get_bts_counters_info(self, counter_id, full_path=None, timeout_for_loading_available_counters=5):
        """
        Keyword for getting full info of bts counters
        :param counter_id:str
        :return: datetime
        """

        timeout = timeout_for_loading_available_counters
        return self.selenium_webui.get_bts_counters_info(counter_id, full_path,
                                                         timeout_for_loading_available_counters=timeout)

    def lock_cell_via_selenium(self):
        """
        Keyword for locking cell on cells page
        """
        self.selenium_webui.lock_cell()

    def unlock_cell_via_selenium(self):
        """
        Keyword for unlocking cell on cells page
        """
        self.selenium_webui.unlock_cell()

    def get_object_namelist_via_selenium(self, name, parameter_name):
        """
        Keyword keyword is responsible for check provided parameter value.
        :name: dist name for parameters to filter
        :param: str, param to locate target parameter, cannot be none
        :return: array of str, specific name list
        """
        return self.selenium_webui.get_object_name_list(name, parameter_name)

    @staticmethod
    def get_load_type():
        from taf.sbts.oam.coam.admin import admin

        api = admin()
        try:
            connection = api.connect_to()
            version = api.get_sw_version(timeout=30, connection=connection)
        except Exception:
            return "SBTS"
        api.teardown(connection=connection)

        return version
